    requires 0 <= start <= end <= a.Length
{
    if start == end then 0
    else
        var maxSum := a[start];
        var currentSum := a[start];
        var i := start + 1;
        while i < end
            invariant start + 1 <= i <= end
            invariant currentSum == sum of a[start..i)
            invariant maxSum >= a[start]
        {
            currentSum := currentSum + a[i];
            if currentSum > maxSum {
                maxSum := currentSum;
